module soda_bottles(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [7:0] a [15:0],\n    input wire [7:0] b [15:0],\n    output reg [3:0] k,\n    output reg [15:0] t,\n    output reg done\n);\n\n    // State declarations\n    localparam [2:0] IDLE       = 3'd0;\n    localparam [2:0] COMPUTE_S  = 3'd1;\n    localparam [2:0] SORT       = 3'd2;\n    localparam [2:0] DP_INIT    = 3'd3;\n    localparam [2:0] DP_UPDATE  = 3'd4;\n    localparam [2:0] FIND_RESULT = 3'd5;\n    localparam [2:0] COMPLETE   = 3'd6;\n\n    reg [2:0] state;\n    reg [3:0] i, j, k_idx;\n    reg [15:0] S;\n    reg [7:0] a_sorted [15:0];\n    reg [7:0] b_sorted [15:0];\n    reg [15:0] dp_addr;\n    reg [11:0] dp_write_data;\n    reg dp_write_en;\n    reg [15:0] max_v;\n    reg [11:0] best_sum;\n    reg [3:0] found_k;\n    reg [15:0] found_t;\n    reg [3:0] pass_cnt;  // For bubble sort passes\n    reg [15:0] visited_v;  // For DP init\n    \n    // DP table: 16 (k) * 4096 (v) = 65536 entries (only use 0-S for each k)\n    reg [11:0] dp_table [0:65535];\n\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            done <= 1'b0;\n            k <= 4'd0;\n            t <= 16'd0;\n            S <= 16'd0;\n            dp_write_en <= 1'b0;\n            for (i = 0; i < 16; i = i + 1) begin\n                a_sorted[i] <= 8'd0;\n                b_sorted[i] <= 8'd0;\n            end\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= COMPUTE_S;\n                        i <= 4'd0;\n                        S <= 16'd0;\n                    end\n                end\n                \n                COMPUTE_S: begin\n                    // Compute total soda and initialize sorted arrays\n                    S <= S + a[i];\n                    a_sorted[i] <= a[i];\n                    b_sorted[i] <= b[i];\n                    if (i == (n - 1)) begin\n                        state <= SORT;\n                        i <= 4'd0;\n                        pass_cnt <= 4'd0;\n                    end else begin\n                        i <= i + 4'd1;\n                    end\n                end\n                \n                SORT: begin\n                    // Bubble sort by b_sorted (descending)\n                    if (pass_cnt < n) begin\n                        if (i < (n - pass_cnt - 4'd1)) begin\n                            if (b_sorted[i] < b_sorted[i+4'd1]) begin\n                                // Swap elements\n                                a_sorted[i] <= a_sorted[i+4'd1];\n                                a_sorted[i+4'd1] <= a_sorted[i];\n                                b_sorted[i] <= b_sorted[i+4'd1];\n                                b_sorted[i+4'd1] <= b_sorted[i];\n                            end\n                            i <= i + 4'd1;\n                        end else begin\n                            i <= 4'd0;\n                            pass_cnt <= pass_cnt + 4'd1;\n                        end\n                    end else begin\n                        // Sorting completed\n                        state <= DP_INIT;\n                        k_idx <= 4'd0;\n                        visited_v <= 16'd0;\n                    end\n                end\n                \n                DP_INIT: begin\n                    // Initialize DP table\n                    if (visited_v <= S) begin\n                        // Initialize all k_idx and v to 12'hFFF (invalid)\n                        dp_table[{k_idx, visited_v[11:0]}] <= 12'hFFF;\n                        visited_v <= visited_v + 16'd1;\n                        if (visited_v == 16'hFFFF) begin\n                            k_idx <= k_idx + 4'd1;\n                            visited_v <= 16'd0;\n                        end\n                    end else begin\n                        if (k_idx < 4'd15) begin\n                            k_idx <= k_idx + 4'd1;\n                            visited_v <= 16'd0;\n                        end else begin\n                            // Initialize dp[0][0] = 0\n                            dp_table[16'd0] <= 12'd0;\n                            state <= DP_UPDATE;\n                            i <= 4'd0;\n                            k_idx <= 4'd15;  // Process k from high to low\n                        end\n                    end\n                end\n                \n                DP_UPDATE: begin\n                    if (i < n) begin\n                        if (visited_v <= S && visited_v >= 16'd1) begin\n                            // Reverse v iteration\n                            if (dp_table[{k_idx - 4'd1, visited_v[11:0]}] != 12'hFFF) begin\n                                // Calculate new v\n                                max_v = (visited_v + b_sorted[i] > S) ? S : (visited_v + b_sorted[i]);\n                                if (dp_table[{k_idx, max_v[11:0]}] < (dp_table[{k_idx - 4'd1, visited_v[11:0]}] + a_sorted[i])) begin\n                                    dp_table[{k_idx, max_v[11:0]}] <= dp_table[{k_idx - 4'd1, visited_v[11:0]}] + a_sorted[i];\n                                end\n                            end\n                            visited_v <= visited_v - 16'd1;\n                        end else begin\n                            // Reset v counter for next k_idx\n                            visited_v <= S;\n                            if (k_idx == 4'd0) begin\n                                // Move to next bottle\n                                i <= i + 4'd1;\n                                k_idx <= 4'd15;\n                            end else begin\n                                k_idx <= k_idx - 4'd1;\n                            end\n                        end\n                    end else begin\n                        // All bottles processed\n                        state <= FIND_RESULT;\n                        k_idx <= 4'd1;  // Start from minimal k=1\n                    end\n                end\n                \n                FIND_RESULT: begin\n                    if (k_idx <= n) begin\n                        if (dp_table[{k_idx[3:0], S[11:0]}] != 12'hFFF) begin\n                            found_k <= k_idx;\n                            found_t <= S - dp_table[{k_idx[3:0], S[11:0]}];\n                            state <= COMPLETE;\n                        end else begin\n                            k_idx <= k_idx + 4'd1;\n                        end\n                    end else begin\n                        // No valid k found (fallback to n)\n                        found_k <= n;\n                        found_t <= 16'd0;\n                        state <= COMPLETE;\n                    end\n                end\n                \n                COMPLETE: begin\n                    k <= found_k;\n                    t <= found_t;\n                    done <= 1'b1;\n                    state <= IDLE;\n                end\n                \n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule